  gallery_images: '',
  description_short: '',
  description_long: '',
  highlights: '',
  opening_hours: '',
  dress_code: 'Smart Casual',
  booking_policy: 'Reservation required',
  cuisine: '',
  best_time: '',
  who_its_for: '',
  insider_tip: '',
  status: 'published' as 'draft' | 'published' | 'archived',
};

