  { code: 'AE', name: 'UAE', flag: '­ƒçª­ƒç¬' },
  { code: 'US', name: 'USA', flag: '­ƒç║­ƒç©' },
  { code: 'GB', name: 'UK', flag: '­ƒç¼­ƒçº' },
  { code: 'IN', name: 'India', flag: '­ƒç«­ƒç│' },
  { code: 'CA', name: 'Canada', flag: '­ƒç¿­ƒçª' },
  { code: 'AU', name: 'Australia', flag: '­ƒçª­ƒç║' },
  { code: 'DE', name: 'Germany', flag: '­ƒç®­ƒç¬' },
  { code: 'FR', name: 'France', flag: '­ƒç½­ƒçÀ' },
  { code: 'SG', name: 'Singapore', flag: '­ƒç©­ƒç¼' },
  { code: 'JP', name: 'Japan', flag: '­ƒç»­ƒçÁ' },
