                      </p>
                    </div>
                      <button
                        onClick={() => setStep('photo')}
                        className="whitespace-nowrap rounded-xl border border-[#D4AF37] bg-[#D4AF37]/10 px-6 py-3 font-medium text-[#D4AF37] transition-all hover:bg-[#D4AF37] hover:text-[#0A0A0A]"
