                        </div>
                      </div>

                      {processedImage && !isProcessing && (
                        <motion.div initial={{ opacity: 0, y: 10 }} animate={{ opacity: 1, y: 0 }} className="mt-12 flex flex-col justify-center gap-4 sm:flex-row">
                          <button 
                            onClick={resetPhoto}
                            className="flex items-center justify-center gap-2 px-6 py-3 text-gray-400 transition-colors hover:text-white"
                          >
                            <RefreshCcw className="w-4 h-4" /> Retake Photo
                          </button>

                          <div className="flex gap-4">
                            <button 
                              onMouseEnter={() => setShowPreview('original')}
                              onMouseLeave={() => setShowPreview('processed')}
                              className="flex items-center justify-center gap-2 rounded-xl border border-[#D4AF37]/50 bg-[#1A1A1A] px-6 py-3 text-[#D4AF37] transition-all hover:bg-[#D4AF37]/10"
                            >
                              Hold for Original
                            </button>

                            <button 
                              onClick={handleDownload}
                              className="flex items-center justify-center gap-2 rounded-xl bg-white px-6 py-3 font-medium text-black transition-all hover:bg-gray-200"
                            >
                              <Download className="w-5 h-5" /> Download HD
                            </button>
                          </div>
                        </motion.div>
                      )}
                    </div>
                  )}
                </div>

                {processedImage && (
                  <div className="border-t border-[#D4AF37]/20 bg-black/35 p-8">
                    <button onClick={() => setStep('lead')} className="flex w-full items-center justify-center gap-2 rounded-xl bg-[#D4AF37] px-8 py-4 font-medium text-[#0A0A0A] transition-all duration-300 hover:bg-[#FFD700]">
                      Submit & Continue Application
                      <ArrowRight className="w-5 h-5" />
                    </button>
                  </div>
                )}
              </div>
            </motion.div>
          )}

          {/* Step 5: Lead Capture */}
          {step === 'lead' && (
            <motion.div key="lead" initial={{ opacity: 0, y: 20 }} animate={{ opacity: 1, y: 0 }} exit={{ opacity: 0, y: -20 }} className="mx-auto max-w-3xl">
              <button onClick={handleBack} className="mb-5 flex items-center gap-2 text-[#D4AF37] transition-colors hover:text-[#FFD700]">
                <ChevronLeft className="w-5 h-5" /> Back
              </button>

              <div className="rounded-3xl border border-[#D4AF37]/30 bg-[#0E0E10]/90 p-7 backdrop-blur-xl sm:p-10">
                <div className="mb-8 text-center">
                  <div className="mx-auto mb-4 flex h-16 w-16 items-center justify-center rounded-full bg-[#D4AF37]/10">
                    <Lock className="w-8 h-8 text-[#D4AF37]" />
                  </div>
                  <p className="font-mono text-xs uppercase tracking-[0.24em] text-[#D4AF37]/75">Step 5</p>
                  <h2 className="mb-2 mt-3 text-3xl font-light text-white">Secure Your Submission</h2>
                  <p className="mx-auto max-w-xl text-gray-400">Enter your official details to proceed with your fast-tracked visa application.</p>
                </div>

                <div className="mb-6 grid grid-cols-1 gap-3 sm:grid-cols-3">
                  <div className="rounded-xl border border-[#D4AF37]/20 bg-black/30 px-4 py-3 text-center text-sm text-gray-300">Route: {passportCountry} {'>'} {destinationCountry}</div>
                  <div className="rounded-xl border border-[#D4AF37]/20 bg-black/30 px-4 py-3 text-center text-sm text-gray-300">Estimated: {result.processingTime}</div>
                  <div className="rounded-xl border border-[#D4AF37]/20 bg-black/30 px-4 py-3 text-center text-sm text-gray-300">Guidance: Concierge Priority</div>
                </div>

                <div className="space-y-5">
                  <div>
                    <label className="mb-2 block text-sm text-gray-400">Full Name *</label>
                    <input type="text" value={formData.fullName} onChange={(e) => setFormData({ ...formData, fullName: e.target.value })} className="w-full rounded-xl border border-[#D4AF37]/20 bg-[#0A0A0A] px-4 py-3 text-white placeholder-gray-600 transition-colors focus:border-[#D4AF37] focus:outline-none" placeholder="Enter your full name as per passport" />
                    {errors.fullName && <p className="text-red-400 text-sm mt-1">{errors.fullName}</p>}
                  </div>
                  <div>
                    <label className="mb-2 block text-sm text-gray-400">Email Address *</label>
                    <input type="email" value={formData.email} onChange={(e) => setFormData({ ...formData, email: e.target.value })} className="w-full rounded-xl border border-[#D4AF37]/20 bg-[#0A0A0A] px-4 py-3 text-white placeholder-gray-600 transition-colors focus:border-[#D4AF37] focus:outline-none" placeholder="your@email.com" />
                    {errors.email && <p className="text-red-400 text-sm mt-1">{errors.email}</p>}
                  </div>
                  <div>
                    <label className="mb-2 block text-sm text-gray-400">Phone Number *</label>
                    <input type="tel" value={formData.phone} onChange={(e) => setFormData({ ...formData, phone: e.target.value })} className="w-full rounded-xl border border-[#D4AF37]/20 bg-[#0A0A0A] px-4 py-3 text-white placeholder-gray-600 transition-colors focus:border-[#D4AF37] focus:outline-none" placeholder="+971 50 123 4567" />
                    {errors.phone && <p className="text-red-400 text-sm mt-1">{errors.phone}</p>}
                  </div>

                  <div className="pt-4">
                    {!isUnlocked ? (
                       <button onClick={handleLeadSubmit} disabled={isSubmitting} className="flex w-full items-center justify-center gap-2 rounded-xl bg-[#D4AF37] px-8 py-4 font-medium text-[#0A0A0A] transition-all duration-300 hover:bg-[#FFD700] disabled:cursor-not-allowed disabled:opacity-70">
                       {isSubmitting ? (
                         <>
                           <div className="w-5 h-5 border-2 border-[#0A0A0A] border-t-transparent rounded-full animate-spin" />
                           Processing...
                         </>
                       ) : (
                         <>
                           <Unlock className="w-5 h-5" />
                           Submit to Concierge
                         </>
                       )}
                     </button>
                    ) : (
                      <div className="rounded-xl border border-emerald-400/30 bg-emerald-400/10 p-6 text-center">
                        <CheckCircle2 className="w-12 h-12 text-emerald-400 mx-auto mb-3" />
                        <h4 className="text-white text-lg font-medium mb-1">Application Submitted</h4>
                        <p className="text-emerald-400/80 text-sm">Your dedicated DALC advisor will contact you shortly.</p>
                      </div>
                    )}
                  </div>
                </div>
              </div>
            </motion.div>
          )}
        </AnimatePresence>
      </div>
    </div>
  );
}

'use client';

import { use } from 'react';
import Link from 'next/link';
import { notFound } from 'next/navigation';
import { motion } from 'motion/react';
import { ArrowLeft, Zap, Users, Fuel, Calendar, MessageCircle } from 'lucide-react';
import Footer from '../../../../components/navigation/Footer';
import {
  getAllCars,
  getCarImage,
  getCarWhatsAppUrl,
} from '../../../../data/transport/carsData';

// ÔöÇÔöÇÔöÇ Component ÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇ

export default function CarDetailPage({ params }: { params: Promise<{ slug: string }> }) {
  const { slug } = use(params);

  const car = getAllCars().find((c) => c.id === slug);

  if (!car) {
    notFound();
  }

  const image = getCarImage(car.id, car.categoryId);
  const whatsappUrl = getCarWhatsAppUrl(car.brand, car.model, car.year);

  const specs = [
    { icon: <Calendar className="w-4 h-4" />, label: 'Year', value: String(car.year) },
    { icon: <Fuel className="w-4 h-4" />, label: 'Fuel', value: car.fuel },
    ...(car.seats ? [{ icon: <Users className="w-4 h-4" />, label: 'Seats', value: `${car.seats} passengers` }] : []),
    ...(car.fuel === 'Electric' ? [{ icon: <Zap className="w-4 h-4" />, label: 'Type', value: 'Electric Vehicle' }] : []),
  ];

  return (
    <div className="min-h-screen bg-luxury-black">
      <div className="max-w-5xl mx-auto px-4 md:px-8 pt-28 pb-24">
        {/* ÔöÇÔöÇ Breadcrumb ÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇ */}
        <nav className="flex items-center gap-2 text-xs text-gray-500 uppercase tracking-widest mb-10">
          <Link href="/travel" className="hover:text-luxury-gold transition-colors">Travel</Link>
          <span>/</span>
          <Link href="/travel/car-rental" className="hover:text-luxury-gold transition-colors">Car Rental</Link>
          <span>/</span>
          <span className="text-luxury-gold">{car.brand} {car.model}</span>
        </nav>

        <div className="grid grid-cols-1 lg:grid-cols-2 gap-12 items-start">
          {/* ÔöÇÔöÇ Image ÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇ */}
          <motion.div
            initial={{ opacity: 0, x: -20 }}
            animate={{ opacity: 1, x: 0 }}
            transition={{ duration: 0.6 }}
            className="relative overflow-hidden border border-white/10"
          >
            <img
              src={image}
              alt={`${car.brand} ${car.model} ${car.year}`}
              className="w-full h-80 lg:h-96 object-cover"
            />
            {car.popular && (
              <span className="absolute top-4 left-4 bg-luxury-gold text-luxury-black text-[10px] font-bold uppercase tracking-widest px-3 py-1">
                Popular
              </span>
            )}
            {car.isNew && (
              <span className="absolute top-4 left-4 bg-white text-luxury-black text-[10px] font-bold uppercase tracking-widest px-3 py-1">
                New
              </span>
            )}
          </motion.div>

          {/* ÔöÇÔöÇ Details ÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇ */}
          <motion.div
            initial={{ opacity: 0, x: 20 }}
            animate={{ opacity: 1, x: 0 }}
            transition={{ duration: 0.6 }}
          >
            <p className="text-luxury-gold text-xs font-bold uppercase tracking-[0.4em] mb-3">
              Car Rental
            </p>
            <h1 className="text-3xl md:text-4xl font-display text-white mb-2">
              {car.brand} {car.model}
            </h1>
            <p className="text-gray-500 text-sm mb-8">{car.year} Model</p>

            {/* Price */}
            <div className="border border-luxury-gold/20 bg-luxury-gold/5 p-5 mb-8">
              <p className="text-gray-400 text-xs uppercase tracking-widest mb-1">Daily Rate</p>
              <p className="text-luxury-gold font-display text-4xl font-bold">
                {car.dailyPrice} <span className="text-xl font-normal">AED</span>
              </p>
              <p className="text-gray-600 text-xs mt-1">Per day ┬À Insurance included</p>
            </div>

            {/* Specs */}
            <div className="grid grid-cols-2 gap-3 mb-8">
              {specs.map(({ icon, label, value }) => (
                <div key={label} className="flex items-center gap-3 border border-white/10 px-4 py-3 bg-white/[0.02]">
                  <span className="text-luxury-gold">{icon}</span>
                  <div>
                    <p className="text-gray-600 text-[10px] uppercase tracking-widest">{label}</p>
                    <p className="text-white text-sm font-medium">{value}</p>
                  </div>
                </div>
              ))}
            </div>

            {/* CTAs */}
            <div className="flex flex-col sm:flex-row gap-3">
              <a
                href={whatsappUrl}
                target="_blank"
                rel="noopener noreferrer"
                className="flex-1 flex items-center justify-center gap-2 px-8 py-4 bg-luxury-gold text-luxury-black text-sm font-bold uppercase tracking-widest hover:bg-luxury-gold/90 transition-all duration-300"
              >
                <MessageCircle className="w-4 h-4" />
                Book via WhatsApp
              </a>
              <Link
                href="/request"
                className="flex-1 flex items-center justify-center gap-2 px-8 py-4 border border-luxury-gold/40 text-luxury-gold text-sm font-bold uppercase tracking-widest hover:bg-luxury-gold/10 transition-all duration-300"
              >
                Request via Concierge
              </Link>
            </div>
