import { useExploreLocations } from '../hooks/useExploreLocations';
import { useFilteredLocations } from '../hooks/useFilteredLocations';
import type { ExploreFilterState, ExploreLocation } from '../types';
import { DEFAULT_FILTERS } from '../types';

type MobileView = 'grid' | 'map';

// Map URL filter params to category names
const FILTER_MAP: Record<string, string> = {
  'landmarks': 'Landmarks',
  'hidden-gems': 'Hidden Gems',
  'attractions': 'Attractions',
  'museums': 'Museums',
  'parks': 'Parks',
  'cultural-sites': 'Cultural Sites',
  'viewpoints': 'Viewpoints',
};

export default function ExplorePage() {
  const params = useParams();
  const filter = params?.filter as string | undefined;
  const [filters, setFilters] = useState<ExploreFilterState>(DEFAULT_FILTERS);
  const [selectedLocation, setSelectedLocation] = useState<ExploreLocation | null>(null);
  const [mobileView, setMobileView] = useState<MobileView>('grid');

  // Apply URL filter on mount
  useEffect(() => {
    if (filter && FILTER_MAP[filter]) {
      setFilters(prev => ({ ...prev, category: FILTER_MAP[filter] }));
    }
  }, [filter]);

  const { data, isLoading, isError } = useExploreLocations();
  const filteredLocations = useFilteredLocations(data, filters);

  const hasActiveFilters =
    filters.emirate !== 'All Emirates' ||
    filters.category !== 'All Categories' ||
    filters.hiddenGems !== 'all' ||
    filters.featured !== 'all' ||
    filters.priceTier !== 'all' ||
    filters.search.trim() !== '';

  const handleLocationSelect = useCallback((loc: ExploreLocation) => {
    setSelectedLocation(loc);
  }, []);

  const handleCollectionSelect = useCallback((patch: Partial<ExploreFilterState>) => {
    setFilters((prev) => ({ ...prev, ...patch }));
  }, []);

  return (
    <div className="flex min-h-screen flex-col bg-[#0B0B0C]">
      <Navbar />

      <ExploreHero />

      <CollectionStrip onCollectionSelect={handleCollectionSelect} />

      {/* ÔöÇÔöÇ Filters (anchor for "Start Exploring" CTA) ÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇ */}
      <div id="explore-filters">
        <ExploreFilters
          filters={filters}
          onChange={setFilters}
          totalCount={data?.length ?? 0}
          filteredCount={filteredLocations.length}
          mobileView={mobileView}
          onMobileViewChange={setMobileView}
        />
      </div>

      {/* ÔöÇÔöÇ Main content ÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇ */}
      <main className="mx-auto w-full max-w-[1600px] flex-1 px-4 sm:px-6 py-6">
        <div className="flex gap-5">

          {/* ÔöÇ Grid panel (left) ÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇ */}
          <div
            className={cn(
              'min-w-0 w-full lg:w-[56%]',
              mobileView === 'map' ? 'hidden lg:block' : 'block',
            )}
          >
            <ExploreGrid
              locations={filteredLocations}
              isLoading={isLoading}
              isError={isError}
              noClient={!supabase}
              hasActiveFilters={hasActiveFilters}
              onLocationSelect={handleLocationSelect}
            />

            {/* Footer below grid on desktop */}
            <div className="mt-16 hidden lg:block">
              <Footer />
            </div>
          </div>

          {/* ÔöÇ Map panel (right, anchor for "View Map" CTA) ÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇ */}
          <div
            id="explore-map"
            className={cn(
              'min-w-0 flex-1 lg:flex-none lg:w-[44%]',
              mobileView === 'grid' ? 'hidden lg:block' : 'block',
            )}
          >
            {/* Sticky map: top = navbar (68px) + filter bar (~54px) + 4px gap */}
            <div className="h-[calc(100svh-130px)] lg:sticky lg:top-[126px] lg:h-[calc(100vh-142px)] min-h-[420px]">
              <ExploreMap
                locations={filteredLocations}
                onLocationSelect={handleLocationSelect}
              />
            </div>
          </div>
        </div>

        {/* Footer on mobile (below map or grid depending on view) */}
        <div className="mt-12 lg:hidden">
          <Footer />
        </div>
      </main>

      {/* ÔöÇÔöÇ Drawer ÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇ */}
      <LocationDrawer
        location={selectedLocation}
        onClose={() => setSelectedLocation(null)}
      />
    </div>
  );
}

