'use client';

import { motion, AnimatePresence } from 'motion/react';
import { X, Check, X as XIcon } from 'lucide-react';
import type { PricingTier } from '../types';

interface TierComparisonModalProps {
  isOpen: boolean;
  onClose: () => void;
  tiers: PricingTier[];
  experienceName: string;
}

const COMPARISON_FEATURES = [
  { key: 'private_guide', label: 'Private Guide', tiers: [false, false, true] },
  { key: 'transport_included', label: 'Transport Included', tiers: [false, true, true] },
  { key: 'champagne', label: 'Champagne Reception', tiers: [false, false, true] },
  { key: 'photography', label: 'Photography Session', tiers: [false, true, true] },
  { key: 'vip_access', label: 'VIP Access', tiers: [false, true, true] },
  { key: 'priority_booking', label: 'Priority Booking', tiers: [false, false, true] },
];

export default function TierComparisonModal({ 
  isOpen, 
  onClose, 
  tiers,
  experienceName 
}: TierComparisonModalProps) {
  // Map tiers to Silver/Gold/Platinum if we have exactly 3, otherwise use actual tier names
  const displayTiers = tiers.length === 3 
    ? [
        { name: 'Silver', color: 'from-gray-400 to-gray-500', tier: tiers[0] },
        { name: 'Gold', color: 'from-amber-400 to-yellow-500', tier: tiers[1] },
        { name: 'Platinum', color: 'from-purple-400 to-pink-500', tier: tiers[2] },
      ]
    : tiers.map((t, i) => ({
        name: t.tier,
        color: i === 0 ? 'from-gray-400 to-gray-500' : i === 1 ? 'from-amber-400 to-yellow-500' : 'from-purple-400 to-pink-500',
        tier: t,
      }));

  return (
    <AnimatePresence>
      {isOpen && (
        <motion.div
          initial={{ opacity: 0 }}
          animate={{ opacity: 1 }}
          exit={{ opacity: 0 }}
          className="fixed inset-0 z-50 flex items-center justify-center px-4 bg-black/80 backdrop-blur-sm"
          onClick={onClose}
        >
          <motion.div
            initial={{ opacity: 0, scale: 0.95, y: 20 }}
            animate={{ opacity: 1, scale: 1, y: 0 }}
            exit={{ opacity: 0, scale: 0.95, y: 10 }}
            transition={{ duration: 0.25 }}
            className="w-full max-w-3xl rounded-2xl border border-luxury-gold/30 bg-[#0E1012] overflow-hidden shadow-2xl max-h-[90vh] overflow-y-auto"
            onClick={(e) => e.stopPropagation()}
          >
            {/* Header */}
            <div className="relative p-6 bg-gradient-to-b from-luxury-gold/10 to-transparent border-b border-white/10">
              <button
                onClick={onClose}
                className="absolute top-4 right-4 p-1 rounded-full text-white/40 hover:text-white/80 hover:bg-white/10 transition-colors"
              >
                <X className="w-5 h-5" />
              </button>
              
              <h2 className="text-2xl font-display text-white mb-1">Compare Tiers</h2>
              <p className="text-white/50 text-sm">{experienceName}</p>
            </div>

            {/* Comparison Table */}
            <div className="p-6">
              <div className="overflow-x-auto">
                <table className="w-full">
                  <thead>
                    <tr>
                      <th className="text-left py-4 px-2 text-white/40 text-xs uppercase tracking-wider font-normal">Feature</th>
                      {displayTiers.map((t, i) => (
                        <th key={i} className="text-center py-4 px-4 min-w-[140px]">
                          <div className={`inline-block px-4 py-2 rounded-lg bg-gradient-to-r ${t.color}`}>
                            <span className="text-black font-bold text-sm">{t.name}</span>
                          </div>
                          <div className="mt-2 text-luxury-gold font-display text-lg">
                            AED {t.tier.price?.toLocaleString() || 'ÔÇö'}
                          </div>
                        </th>
                      ))}
                    </tr>
                  </thead>
                  <tbody>
                    {COMPARISON_FEATURES.map((feature, idx) => (
                      <tr key={feature.key} className={idx % 2 === 0 ? 'bg-white/[0.02]' : ''}>
                        <td className="py-3 px-2 text-white/70 text-sm">{feature.label}</td>
                        {feature.tiers.map((included, i) => (
                          <td key={i} className="text-center py-3 px-4">
                            {included ? (
                              <Check className="w-5 h-5 text-emerald-400 mx-auto" />
                            ) : (
                              <XIcon className="w-5 h-5 text-white/20 mx-auto" />
                            )}
                          </td>
                        ))}
                      </tr>
                    ))}
                    {/* What's Included Row */}
                    <tr className="border-t border-white/10">
                      <td className="py-4 px-2 text-white/70 text-sm align-top">What's Included</td>
                      {displayTiers.map((t, i) => (
                        <td key={i} className="py-4 px-4 align-top">
                          <ul className="text-xs text-white/50 space-y-1">
                            {t.tier.includes?.map((item, j) => (
                              <li key={j} className="flex items-start gap-1.5">
                                <Check className="w-3 h-3 text-luxury-gold flex-shrink-0 mt-0.5" />
                                <span>{item}</span>
                              </li>
                            )) || <li className="text-white/30">Basic inclusions</li>}
                          </ul>
                        </td>
                      ))}
                    </tr>
                  </tbody>
                </table>
              </div>

              <p className="text-xs text-white/30 text-center mt-6">
                Features may vary by experience. Contact concierge for custom packages.
              </p>
            </div>
          </motion.div>
        </motion.div>
      )}
    </AnimatePresence>
  );
}

'use client';

import Link from 'next/link';
import { motion } from 'motion/react';
import { Calendar, Clock, ArrowRight, Sparkles } from 'lucide-react';
import { useUpcomingEvents } from '../hooks/useExperiences';
import type { ExperienceService } from '../types';

function EventCard({ event, index }: { event: ExperienceService; index: number }) {
  const eventDate = event.event_date ? new Date(event.event_date) : null;
  const daysUntil = eventDate 
    ? Math.ceil((eventDate.getTime() - Date.now()) / (1000 * 60 * 60 * 24))
    : null;

  return (
    <motion.article
      initial={{ opacity: 0, x: 20 }}
      animate={{ opacity: 1, x: 0 }}
      transition={{ delay: index * 0.1, duration: 0.4 }}
      className="flex-shrink-0 w-[300px] group"
    >
      <Link 
        href={`/experiences/tickets-and-culture/${event.slug}`}
        className="block h-full border border-white/10 bg-white/[0.02] overflow-hidden hover:border-luxury-gold/40 transition-all duration-300"
      >
        {/* Image */}
        <div className="relative h-40 overflow-hidden">
          <img
            src={event.hero_image || '/images/placeholder-experience.jpg'}
            alt={event.name}
            className="w-full h-full object-cover transition-transform duration-500 group-hover:scale-110"
          />
          <div className="absolute inset-0 bg-gradient-to-t from-black/80 via-black/20 to-transparent" />
          
          {/* Days until badge */}
          {daysUntil !== null && (
            <div className="absolute top-3 left-3">
              <div className={`inline-flex items-center gap-1.5 px-2.5 py-1 rounded-full text-xs font-medium ${
                daysUntil <= 3 
                  ? 'bg-red-500/20 text-red-400 border border-red-500/30' 
                  : daysUntil <= 7 
                    ? 'bg-amber-500/20 text-amber-400 border border-amber-500/30'
                    : 'bg-emerald-500/20 text-emerald-400 border border-emerald-500/30'
              }`}>
                <Sparkles className="w-3 h-3" />
                {daysUntil === 0 ? 'Today!' : daysUntil === 1 ? 'Tomorrow' : `${daysUntil} days`}
              </div>
            </div>
          )}

          {/* Date badge */}
          {eventDate && (
            <div className="absolute bottom-3 left-3 right-3">
              <div className="flex items-center gap-2 text-white">
                <div className="bg-luxury-gold text-luxury-black px-2 py-1 text-center min-w-[48px]">
                  <div className="text-[10px] uppercase font-bold tracking-wider">
                    {eventDate.toLocaleDateString('en-US', { month: 'short' })}
                  </div>
                  <div className="text-lg font-bold leading-none">
                    {eventDate.getDate()}
                  </div>
                </div>
                <div className="flex-1 min-w-0">
                  <p className="text-xs text-white/60 truncate">
                    {eventDate.toLocaleDateString('en-US', { weekday: 'long' })}
                  </p>
                  <p className="text-sm font-medium truncate">{event.name}</p>
                </div>
              </div>
            </div>
          )}
        </div>

        {/* Content */}
        <div className="p-4">
          <p className="text-gray-400 text-xs uppercase tracking-wider mb-1">
            {event.venue_name || 'Dubai Experience'}
          </p>
          <h3 className="text-white font-display text-sm mb-3 line-clamp-2 group-hover:text-luxury-gold transition-colors">
            {event.name}
          </h3>
          
          <div className="flex items-center justify-between">
            <div className="flex items-center gap-3 text-xs text-gray-500">
              <span className="flex items-center gap-1">
                <Clock className="w-3 h-3" />
                {event.duration_minutes ? `${Math.round(event.duration_minutes / 60)}h` : 'TBD'}
              </span>
              {event.price_from && (
                <span className="text-luxury-gold">
                  From AED {event.price_from.toLocaleString()}
                </span>
              )}
            </div>
            <ArrowRight className="w-4 h-4 text-luxury-gold opacity-0 group-hover:opacity-100 transition-opacity" />
          </div>
        </div>
      </Link>
    </motion.article>
  );
}

export default function UpcomingEventsStrip() {
  const { data: events = [], isLoading } = useUpcomingEvents(6);

  if (isLoading) {
    return (
      <section className="py-16 border-t border-white/10">
        <div className="max-w-7xl mx-auto px-4 md:px-8">
          <div className="flex items-center gap-3 mb-8">
            <div className="w-10 h-10 bg-white/5 rounded-lg animate-pulse" />
            <div className="h-6 w-48 bg-white/5 rounded animate-pulse" />
          </div>
          <div className="flex gap-4 overflow-hidden">
            {[1, 2, 3, 4].map((i) => (
              <div key={i} className="flex-shrink-0 w-[300px] h-[280px] bg-white/5 animate-pulse" />
            ))}
          </div>
        </div>
      </section>
    );
  }

  if (events.length === 0) {
    return null;
  }

  return (
    <section className="py-16 border-t border-white/10">
      <div className="max-w-7xl mx-auto px-4 md:px-8">
        {/* Header */}
        <div className="flex items-center justify-between mb-8">
          <div className="flex items-center gap-3">
            <div className="w-10 h-10 rounded-lg bg-luxury-gold/10 border border-luxury-gold/30 flex items-center justify-center">
              <Calendar className="w-5 h-5 text-luxury-gold" />
            </div>
            <div>
              <h2 className="text-xl font-display text-white">This Week in Dubai</h2>
              <p className="text-gray-500 text-sm">Upcoming exclusive events and experiences</p>
            </div>
          </div>
          <Link 
            href="/experiences/tickets-and-culture"
            className="hidden sm:flex items-center gap-2 text-luxury-gold text-sm hover:text-white transition-colors"
          >
            View All Events <ArrowRight className="w-4 h-4" />
          </Link>
        </div>

        {/* Horizontal Scroll */}
        <div className="relative">
          <div className="flex gap-4 overflow-x-auto pb-4 scrollbar-hide snap-x snap-mandatory">
            {events.map((event, index) => (
              <div key={event.id} className="snap-start">
                <EventCard event={event} index={index} />
              </div>
            ))}
          </div>
          
          {/* Fade edges */}
          <div className="absolute top-0 right-0 bottom-4 w-24 bg-gradient-to-l from-luxury-black to-transparent pointer-events-none" />
        </div>
      </div>
    </section>
  );
}

'use client';

import { useState } from 'react';
import { motion, AnimatePresence } from 'motion/react';
import { X, Clock, CheckCircle, Loader2 } from 'lucide-react';
import { useJoinWaitlist, useWaitlistStatus } from '../hooks/useWaitlist';
import { useAppStore } from '../../../store/useAppStore';
import type { ExperienceService } from '../types';

interface WaitlistModalProps {
  isOpen: boolean;
  onClose: () => void;
  experience: ExperienceService;
  selectedDate?: string;
  selectedTimeSlot?: string;
}

export default function WaitlistModal({ 
  isOpen, 
  onClose, 
  experience, 
  selectedDate,
  selectedTimeSlot 
}: WaitlistModalProps) {
  const [submitted, setSubmitted] = useState(false);
  const profile = useAppStore((s) => s.profile);
  const session = useAppStore((s) => s.session);
  
  const { data: existingEntry } = useWaitlistStatus(experience.id, session?.user?.id);
  const joinWaitlist = useJoinWaitlist();

  const handleJoin = async () => {
    if (!session?.user?.id) return;
    
    try {
      await joinWaitlist.mutateAsync({
        experience_id: experience.id,
        user_id: session.user.id,
        time_slot: selectedTimeSlot,
        booking_date: selectedDate,
      });
      setSubmitted(true);
    } catch (error) {
      console.error('Failed to join waitlist:', error);
    }
  };

  const isAlreadyOnWaitlist = !!existingEntry;

  return (
    <AnimatePresence>
      {isOpen && (
        <motion.div
          initial={{ opacity: 0 }}
          animate={{ opacity: 1 }}
          exit={{ opacity: 0 }}
          className="fixed inset-0 z-50 flex items-center justify-center px-4 bg-black/80 backdrop-blur-sm"
          onClick={onClose}
        >
          <motion.div
            initial={{ opacity: 0, scale: 0.95, y: 20 }}
            animate={{ opacity: 1, scale: 1, y: 0 }}
            exit={{ opacity: 0, scale: 0.95, y: 10 }}
            transition={{ duration: 0.25 }}
            className="w-full max-w-md rounded-2xl border border-luxury-gold/30 bg-[#0E1012] overflow-hidden shadow-2xl"
            onClick={(e) => e.stopPropagation()}
          >
            {/* Header */}
            <div className="relative p-6 bg-gradient-to-b from-luxury-gold/10 to-transparent border-b border-white/10">
              <button
                onClick={onClose}
                className="absolute top-4 right-4 p-1 rounded-full text-white/40 hover:text-white/80 hover:bg-white/10 transition-colors"
              >
                <X className="w-5 h-5" />
              </button>
              
              <div className="flex items-center gap-3">
                <div className="w-12 h-12 rounded-xl bg-luxury-gold/20 flex items-center justify-center">
                  <Clock className="w-6 h-6 text-luxury-gold" />
                </div>
                <div>
                  <h2 className="text-xl font-display text-white">
                    {isAlreadyOnWaitlist ? 'You\'re on the List!' : 'Join Waitlist'}
                  </h2>
                  <p className="text-white/50 text-sm">
                    {experience.name}
                  </p>
                </div>
              </div>
            </div>

            {/* Content */}
            <div className="p-6">
              {submitted || isAlreadyOnWaitlist ? (
                <div className="text-center py-4">
                  <div className="w-16 h-16 rounded-full bg-emerald-500/20 flex items-center justify-center mx-auto mb-4">
                    <CheckCircle className="w-8 h-8 text-emerald-400" />
                  </div>
                  <h3 className="text-lg text-white mb-2">
                    {isAlreadyOnWaitlist ? 'Already Registered' : 'You\'re on the Waitlist!'}
                  </h3>
                  <p className="text-white/50 text-sm mb-6">
                    {isAlreadyOnWaitlist 
                      ? 'We\'ll notify you when a spot opens up.'
                      : 'We\'ll notify you via email and in-app notification when a spot becomes available.'
                    }
                  </p>
                  
                  {selectedDate && (
                    <div className="bg-white/5 rounded-lg p-4 text-left mb-4">
                      <p className="text-xs text-white/40 uppercase tracking-wider mb-1">Preferred Date</p>
                      <p className="text-white text-sm">{new Date(selectedDate).toLocaleDateString('en-US', { weekday: 'long', month: 'long', day: 'numeric' })}</p>
                      {selectedTimeSlot && (
                        <>
                          <p className="text-xs text-white/40 uppercase tracking-wider mb-1 mt-2">Preferred Time</p>
                          <p className="text-white text-sm">{selectedTimeSlot}</p>
                        </>
                      )}
                    </div>
                  )}

                  <button
                    onClick={onClose}
                    className="w-full py-3 px-6 rounded-xl bg-luxury-gold text-luxury-black font-semibold hover:bg-luxury-gold/90 transition-colors"
                  >
                    Got it
                  </button>
                </div>
              ) : (
                <>
                  <div className="bg-white/5 rounded-lg p-4 mb-6">
                    <p className="text-white/70 text-sm mb-4">
                      This experience is currently sold out. Join the waitlist and we\'ll notify you immediately when a spot opens up.
                    </p>
                    
                    {selectedDate && (
                      <div className="border-t border-white/10 pt-4 mt-4">
                        <p className="text-xs text-white/40 uppercase tracking-wider mb-1">Requested Date</p>
                        <p className="text-white">{new Date(selectedDate).toLocaleDateString('en-US', { weekday: 'long', month: 'long', day: 'numeric' })}</p>
                        {selectedTimeSlot && (
                          <>
                            <p className="text-xs text-white/40 uppercase tracking-wider mb-1 mt-2">Requested Time</p>
                            <p className="text-white">{selectedTimeSlot}</p>
                          </>
                        )}
                      </div>
                    )}
                  </div>

                  {!session?.user ? (
                    <div className="text-center py-4">
                      <p className="text-white/50 text-sm mb-4">Sign in to join the waitlist</p>
                      <a
                        href="/auth/login"
                        className="inline-block w-full py-3 px-6 rounded-xl bg-luxury-gold text-luxury-black font-semibold hover:bg-luxury-gold/90 transition-colors text-center"
                      >
                        Sign In
                      </a>
                    </div>
                  ) : (
                    <div className="space-y-3">
                      <button
                        onClick={handleJoin}
                        disabled={joinWaitlist.isPending}
                        className="w-full py-3 px-6 rounded-xl bg-luxury-gold text-luxury-black font-semibold hover:bg-luxury-gold/90 transition-colors flex items-center justify-center gap-2 disabled:opacity-50"
                      >
                        {joinWaitlist.isPending ? (
                          <>
                            <Loader2 className="w-4 h-4 animate-spin" />
                            Joining...
                          </>
                        ) : (
                          'Join Waitlist'
                        )}
                      </button>
                      <button
                        onClick={onClose}
                        className="w-full py-3 px-6 rounded-xl border border-white/10 text-white/60 hover:text-white hover:border-white/20 transition-colors"
                      >
                        Maybe Later
                      </button>
                    </div>
                  )}
                </>
              )}
            </div>
          </motion.div>
        </motion.div>
      )}
    </AnimatePresence>
  );
}

'use client';

import { use, useState } from 'react';
