function MenuModal({ restaurant: r, onClose, onBlogOpen }: {
  restaurant: Restaurant;
  onClose: () => void;
  onBlogOpen: () => void;
}) {
  const sections = getMenuData(r.name, r.cuisine, r.price_tier);

  return (
    <motion.div
      initial={{ opacity: 0 }}
      animate={{ opacity: 1 }}
      exit={{ opacity: 0 }}
      className="fixed inset-0 z-50 flex items-center justify-center p-4 md:p-8"
      onClick={onClose}
    >
      <div className="absolute inset-0 bg-[#080706]/90 backdrop-blur-md" />

      <motion.div
        initial={{ opacity: 0, scale: 0.96 }}
        animate={{ opacity: 1, scale: 1 }}
        exit={{ opacity: 0, scale: 0.96 }}
        transition={{ duration: 0.4, ease: [0.22, 1, 0.36, 1] }}
        onClick={e => e.stopPropagation()}
        className="relative bg-[#0f0d0b] border border-[#F5EDD8]/8 rounded-3xl w-full max-w-2xl max-h-[90vh] overflow-y-auto"
      >
        <div className="flex items-center justify-between p-6 border-b border-[#F5EDD8]/8">
          <div>
            <div className="text-[#C9A84C] text-[10px] font-bold uppercase tracking-widest mb-1">{r.cuisine}</div>
            <h3 className="font-['Cormorant_Garamond'] text-2xl text-[#F5EDD8]">{r.name} ÔÇö Menu</h3>
          </div>
          <div className="flex items-center gap-2">
