        >
          <ChevronRight className="w-10 h-10" strokeWidth={1} />
        </button>

        {/* Carousel Indicators */}
        <div className="absolute bottom-8 right-8 z-20 flex gap-2 hidden md:flex">
          {allImages.map((_, i) => (
            <button
              key={i}
